
let hands,face;
self.onmessage=async({data})=>{try{if(data.type==='init'){const {FilesetResolver,HandLandmarker,FaceLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');hands=await HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:2,minHandDetectionConfidence:.6,minTrackingConfidence:.6});face=await FaceLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task'},runningMode:'VIDEO',numFaces:1});self.postMessage({type:'ready'});}else if(data.type==='frame'){const h=hands.detectForVideo(data.bitmap,data.time),f=face.detectForVideo(data.bitmap,data.time);data.bitmap.close();self.postMessage({type:'result',hands:h.landmarks,face:f.faceLandmarks[0]||[],time:data.time});}}catch(e){data.bitmap?.close();self.postMessage({type:'error',message:e.message});}};
